<?php

namespace App\Policies;

use App\Models\StockMovement;
use App\Models\User;

/**
 * StockMovementPolicy — Inventory movement audit log.
 *
 * StockMovements are the immutable ledger of all stock changes.
 * They are auto-generated by:
 *   - Order fulfilment (OUT movements)
 *   - Import receipts (IN movements)
 *   - Stock take adjustments (ADJUSTMENT movements)
 *   - Transfer orders (TRANSFER movements)
 *
 * Update and delete are intentionally absent — movements are immutable
 * for audit trail integrity (no retroactive modifications allowed).
 *
 * Role matrix:
 *  view  : admin, manager, warehouse, accountant, viewer
 *  create: admin, warehouse (manual stock adjustment — exceptional use only)
 *
 * Tenant isolation: StockMovement has no direct tenant_id.
 * See StockPolicy for explanation of the isolation approach.
 */
class StockMovementPolicy extends BaseTenantPolicy
{
    public function viewAny(User $user): bool
    {
        return $user->tenant_id !== null
            && $user->hasAnyRole(['admin', 'manager', 'warehouse', 'accountant', 'viewer']);
    }

    public function view(User $user, StockMovement $stockMovement): bool
    {
        return $user->tenant_id !== null
            && $user->hasAnyRole(['admin', 'manager', 'warehouse', 'accountant', 'viewer']);
    }

    /**
     * Manual stock adjustment — creates a correction movement.
     * Restricted to admin and warehouse role; requires a note explaining the reason.
     */
    public function create(User $user): bool
    {
        return $user->tenant_id !== null
            && $user->hasAnyRole(['admin', 'warehouse']);
    }
}
